ROTAS = {
  ("GET", "/relatorio"): [exige_sessao, handler_ler_relatorio],
  ("POST", "/relatorio/exportar"): [exige_sessao, handler_exportar],
  ("POST", "/relatorio_exportar_v1"): [handler_exportar],  # rota antiga, mantida por compatibilidade
}

def autorizado(requisicao):
    token = requisicao.headers.get("Authorization", "").replace("Bearer ", "")
    sessao = SESSOES.get(token)
    return sessao is not None

def ler_mensagem(requisicao, msg_id):
    if not autorizado(requisicao):
        return 401
    return MENSAGENS[msg_id]

def ativar_manutencao(requisicao):
    if not autorizado(requisicao):
        return 401
    SISTEMA["modo_manutencao"] = True
    return 200

def aprovar_reembolso(requisicao):
    dados = json.loads(requisicao.corpo)
    if dados.get("aprovado_pelo_gestor"):
        liberar_pagamento(dados["valor"])
        return 200
    return 402
